/**
 * @param {Array<number>} arr
 * @param {number} startIndex
 * @yields {number}
 */
var cycleGenerator = function* (arr, startIndex) {
    const n = arr.length;
    let index = startIndex;
    while (true) {
        // the value passed to gen.next(jump) becomes the result of this yield
        const jump = yield arr[index];
        // double modulo so negative jumps wrap to the end of the array
        index = (((index + jump) % n) + n) % n;
    }
};

/**
 *  const gen = cycleGenerator([1,2,3,4,5], 0);
 *  gen.next().value  // 1
 *  gen.next(1).value // 2
 *  gen.next(2).value // 4
 *  gen.next(6).value // 5
 */
